\title{Dream Logic: Coexisting Contradictions in Four-Valued\\
Paraconsistency and Their Topological Models}
\author{Aristotle}
\date{2026-06-19}

\begin{document}
\maketitle

\begin{abstract}
We present a fully formalized account of \emph{paraconsistent} reasoning ---
logic in which a contradiction is a contained, local phenomenon rather than a
global catastrophe --- together with its precise topological semantics. On the
algebraic side we formalize Belnap's four-valued logic $\FOUR$ (the logic of
First-Degree Entailment), whose values are $\tru$, $\fls$, $\bothv$ (a
\emph{glut}: information asserting a proposition and its negation), and
$\neitherv$ (a \emph{gap}: no information either way). We prove that the Law of
Non-Contradiction can fail (\texttt{lnc\_can\_fail}), that the Law of Excluded
Middle can fail (\texttt{lem\_can\_fail}), and --- the defining feature of
paraconsistency --- that \emph{ex contradictione quodlibet} (``explosion'')
fails (\texttt{explosion\_fails}). We characterize the impossible objects
exactly: $\bothv$ is the unique glut (\texttt{glut\_iff}) and $\neitherv$ is the
unique gap (\texttt{gap\_iff}), and we certify the contrast with classical logic
(\texttt{classical\_no\_glut}, \texttt{classical\_explosion}). On the geometric
side we develop the closed-set co-Heyting model: with paraconsistent negation
$\pneg A := \closure(A^{c})$ and contradiction set $\contra A := A \cap \pneg A$,
we prove that for a closed set the contradiction set is exactly the frontier
(\texttt{contradiction\_eq\_frontier}), that the Law of Non-Contradiction holds
for a closed set iff it is \emph{clopen} (\texttt{lnc\_holds\_iff\_clopen}), and
that on a preconnected space every proper nonempty closed set carries a nonempty
contradiction set (\texttt{connected\_forces\_paraconsistency}). A concrete
dialetheia is exhibited in $\mathbb{R}$: the point $0$ is a coexisting
contradiction of $[0,1]$ (\texttt{dream\_object\_real}). The two developments are
linked by the dictionary identifying a topological frontier point with the
Belnap glut value $\bothv$.
\end{abstract}

\section{Introduction}

Classical logic is governed by two Aristotelian principles. The \emph{Law of
Non-Contradiction} (LNC) forbids any proposition from being both true and false.
The principle of \emph{explosion}, \emph{ex contradictione quodlibet} (ECQ),
states that from a contradiction every proposition follows: $P,\ \neg P \vdash Q$
for arbitrary $Q$. ECQ makes classical logic brittle with respect to
inconsistency: a single accepted contradiction trivializes the entire theory.

Real reasoning --- scientific theories under anomaly, knowledge bases merged from
conflicting sources, legal and ethical deliberation, and the phenomenology of
dreams --- routinely tolerates local inconsistency without collapsing into
triviality. \emph{Paraconsistent} logics formalize this: ECQ fails, so
contradictions can be quarantined. \emph{Dialetheic} positions accept that some
contradictions are true; the true-and-false propositions are \emph{dialetheias},
or \emph{impossible objects} --- objects coexisting with their own negation.

We formalize two complementary faces of paraconsistency and prove they are
aspects of one phenomenon: (1) an algebraic semantics --- Belnap's four-valued
logic $\FOUR$, the canonical matrix for First-Degree Entailment; and (2) a
topological semantics --- the co-Heyting algebra of closed sets, where the
dialetheias are precisely boundary points. The bridge is the central payoff: a
topological frontier point is a Belnap glut. All results below are mechanically
verified.

\paragraph{Note on the guiding slogan.} The informal brief spoke of ``spaces
where open sets are not closed under arbitrary union.'' Taken literally this is
false: the topology axioms require open sets to be closed under arbitrary union.
A methodological finding is that the correct dual reading is ``closed sets need
not be open,'' and paraconsistency lives exactly in the gap between
\emph{closed} and \emph{clopen} (Theorem~\ref{thm:lnc-clopen}).

\section{The four-valued logic $\FOUR$}

\begin{definition}[Truth values]
Let $\FOUR = \{\tru,\fls,\bothv,\neitherv\}$. The values answer ``what does our
information say?'': $\tru$ (established to hold), $\fls$ (established to fail),
$\bothv$ (a \emph{glut}: asserted to hold and to fail), $\neitherv$ (a
\emph{gap}: no information).
\end{definition}

\begin{definition}[Truth order]
$\FOUR$ is partially ordered by information truth-content, with $\fls$ least,
$\tru$ greatest, and $\bothv,\neitherv$ incomparable (the ``diamond''):
\[
\fls < \bothv < \tru, \qquad \fls < \neitherv < \tru, \qquad
\bothv \parallel \neitherv .
\]
\end{definition}

\begin{definition}[Connectives]
$\conj$ (conjunction) is the lattice meet; $\disj$ (disjunction) is the join;
$\negf$ (negation) is the order-reversing involution that swaps $\tru
\leftrightarrow \fls$ and fixes the impossible objects: $\negf\bothv = \bothv$,
$\negf\neitherv = \neitherv$. For example $\bothv \conj \fls = \fls$, $\bothv
\conj \tru = \bothv$, $\neitherv \disj \fls = \neitherv$, $\neitherv \disj \tru =
\tru$.
\end{definition}

\begin{definition}[Designation]
A value is \emph{designated} (asserted, believed) iff it carries at least a grain
of truth: $\designated x :\Longleftrightarrow x = \tru \lor x = \bothv$.
\end{definition}

\begin{definition}[Glut, gap]
$x$ is a \emph{glut} iff $\designated(x \conj \negf x)$; $x$ is a \emph{gap} iff
$\neg\,\designated(x \disj \negf x)$.
\end{definition}

\begin{theorem}[\texttt{glut\_iff}]\label{thm:glut}
$x$ is a glut iff $x = \bothv$.
\end{theorem}
\begin{proof}[Proof sketch]
Finite case analysis. $\tru \conj \negf\tru = \fls$ (undesignated); $\fls$
symmetric; $\neitherv \conj \neitherv = \neitherv$ (undesignated); $\bothv \conj
\negf\bothv = \bothv$ (designated). Only $\bothv$ qualifies.
\end{proof}

\begin{theorem}[\texttt{gap\_iff}]\label{thm:gap}
$x$ is a gap iff $x = \neitherv$.
\end{theorem}
\begin{proof}[Proof sketch]
Dual case analysis: $\disj$ with $\negf$ is designated for $\tru,\fls,\bothv$ and
equals $\neitherv$ only at $\neitherv$.
\end{proof}

\begin{theorem}[\texttt{lnc\_can\_fail}]
There is $x$ with $\designated(x \conj \negf x)$: LNC fails in $\FOUR$.
\end{theorem}
\begin{proof}[Proof sketch]
Witness $x = \bothv$ (Theorem~\ref{thm:glut}).
\end{proof}

\begin{theorem}[\texttt{lem\_can\_fail}]
There is $x$ with $\neg\,\designated(x \disj \negf x)$: LEM fails.
\end{theorem}
\begin{proof}[Proof sketch]
Witness $x = \neitherv$ (Theorem~\ref{thm:gap}).
\end{proof}

\begin{theorem}[\texttt{explosion\_fails}, paraconsistency]\label{thm:explosion}
There are $p,q$ with $p$ and $\negf p$ both designated yet $q$ not designated;
hence the schema ``from $p$ and $\negf p$, conclude $q$'' is invalid.
\end{theorem}
\begin{proof}[Proof sketch]
Take $p = \bothv$, $q = \fls$. Then $p$ and $\negf p = \bothv$ are designated,
but $q = \fls$ is not. The isolated glut does not propagate.
\end{proof}

Together with the previous theorem, $\FOUR$ is both \emph{paraconsistent}
(tolerates gluts) and \emph{paracomplete} (tolerates gaps).

\begin{theorem}[\texttt{classical\_no\_glut}]
In the two-valued Boolean algebra with $\designated b := (b = \tru)$, no value is
a glut: $b \land \neg b$ is never designated.
\end{theorem}

\begin{theorem}[\texttt{classical\_explosion}]
In the Boolean algebra, ECQ holds: if $b$ and $\neg b$ are designated then every
$c$ is designated.
\end{theorem}

\section{The topological model of paraconsistency}

Throughout, $X$ is a topological space, $A^{c}$ the complement, and
$\front A = \closure A \cap \closure(A^{c})$.

\begin{definition}[Paraconsistent negation]
For $A \subseteq X$, $\pneg A := \closure(A^{c})$.
\end{definition}

\begin{definition}[Contradiction set]
$\contra A := A \cap \pneg A = A \cap \closure(A^{c})$. Its points lie in $A$ and
are limits of points outside $A$ --- topological dialetheias.
\end{definition}

\begin{theorem}[\texttt{contradiction\_eq\_frontier}]\label{thm:contra-frontier}
If $A$ is closed then $\contra A = \front A$.
\end{theorem}
\begin{proof}[Proof sketch]
$\front A = \closure A \cap \closure(A^{c})$; for closed $A$, $\closure A = A$, so
$\front A = A \cap \closure(A^{c}) = A \cap \pneg A = \contra A$.
\end{proof}

\begin{theorem}[\texttt{lnc\_holds\_iff\_clopen}]\label{thm:lnc-clopen}
For closed $A$, $\contra A = \emptyset \iff A$ is clopen.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:contra-frontier}, $\contra A = \emptyset \iff \front A =
\emptyset$, and a set is clopen iff its frontier is empty.
\end{proof}

\begin{corollary}[\texttt{not\_clopen\_contradiction}]\label{cor:notclopen}
A closed set that is not clopen has a nonempty contradiction set.
\end{corollary}

Theorem~\ref{thm:lnc-clopen} is the precise form of the guiding slogan: classical
behavior occurs exactly on clopen sets; paraconsistency appears precisely where a
closed set fails to be open.

\begin{theorem}[\texttt{dream\_object\_real}]\label{thm:dream-real}
In $\mathbb{R}$, $0 \in \contra([0,1])$.
\end{theorem}
\begin{proof}[Proof sketch]
$[0,1]$ is closed, so $\contra([0,1]) = \front[0,1] = \{0,1\}$, which contains
$0$.
\end{proof}

\begin{corollary}[\texttt{contradiction\_nonempty\_real}]
$\contra([0,1])$ is nonempty in $\mathbb{R}$.
\end{corollary}

\begin{theorem}[\texttt{connected\_forces\_paraconsistency}]\label{thm:connected}
Let $X$ be preconnected and $A \subseteq X$ closed with $A$ and $A^{c}$ both
nonempty. Then $\contra A$ is nonempty.
\end{theorem}
\begin{proof}[Proof sketch]
By Corollary~\ref{cor:notclopen} it suffices that $A$ is not clopen. In a
preconnected space the only clopen sets are $\emptyset$ and $X$; $A = \emptyset$
contradicts $A$ nonempty and $A = X$ contradicts $A^{c}$ nonempty. Hence $A$ is
not clopen.
\end{proof}

\paragraph{Interpretation.} On a connected space the only
contradiction-free closed beliefs are the trivial ones; every proper belief is
dialetheic. Geometric unity \emph{forces} dream logic. The hypotheses are
load-bearing: dropping properness allows $A = X$ with empty frontier.

\section{The bridge: frontier points are gluts}

For closed $A$, define a valuation $\mathrm{val}_A : X \to \FOUR$ by membership in
$A$ and $\pneg A$: in $A$ only $\mapsto \tru$; in $\pneg A$ only $\mapsto \fls$;
in both $\mapsto \bothv$; in neither $\mapsto \neitherv$. Since $A \cup \pneg A =
X$ for closed $A$, the value $\neitherv$ does not occur.

\paragraph{Bridge principle (\texttt{val\_both\_iff\_frontier}).}
$\mathrm{val}_A x = \bothv \iff x \in \front A$. With
Theorem~\ref{thm:contra-frontier} (\texttt{glut\_iff\_contradiction}): a point
receives the glut value $\bothv$ exactly when it is a coexisting contradiction of
$A$. The witness of Theorem~\ref{thm:dream-real} is then a literal glut
(\texttt{dream\_object\_real\_is\_glut}). This identifies the unique glut value of
Theorem~\ref{thm:glut} with the boundary points of
Theorem~\ref{thm:contra-frontier}.

\section{Algorithms}

\paragraph{Bilattice evaluation.} Encode each value by evidence bits $(t,f)$:
$\tru=(1,0)$, $\fls=(0,1)$, $\bothv=(1,1)$, $\neitherv=(0,0)$. Then $x \conj y =
(t_x\land t_y,\ f_x \lor f_y)$, $x \disj y = (t_x \lor t_y,\ f_x \land f_y)$,
$\negf(t,f)=(f,t)$, and $\designated(t,f) := (t=1)$. Evaluation is $O(1)$ per
connective; an $n$-variable formula is checked over all $4^{n}$ assignments in
$O(4^{n}\cdot|\text{formula}|)$.

\paragraph{Countermodel search.} For ``premises $\vdash$ conclusion,'' search all
$4^{n}$ assignments for one making premises designated and conclusion
undesignated. On $P,\negf P \vdash Q$ this returns $P=\bothv$, $Q=\fls$,
mechanizing Theorem~\ref{thm:explosion}.

\paragraph{Frontier extraction.} On a discretized domain, approximate $\contra A
= \front A$ by flagging points of $A$ adjacent to the outside; this recovers
$\{0,1\}$ for $[0,1]$, realizing Theorem~\ref{thm:contra-frontier}.

\section{Applications}
\begin{itemize}[nosep]
  \item Inconsistency-tolerant databases and knowledge fusion (gluts queried
  without explosion, Theorem~\ref{thm:explosion}).
  \item Belief revision: gaps model retraction; interior/closure give idempotent
  retraction/revision operators.
  \item Spatial reasoning: Theorem~\ref{thm:contra-frontier} ties boundaries to a
  logical semantics; Theorem~\ref{thm:connected} explains why connected regions
  resist contradiction-free description.
  \item Robust automated reasoning: a paraconsistent core stops one faulty axiom
  from trivializing a theory.
\end{itemize}

\section{Discussion}

The algebraic $\FOUR$ makes the logical content sharp (LNC and LEM fail at one
value each; explosion fails because designation does not propagate through an
isolated glut); the topological model makes the structural content sharp
(dialetheias are boundaries; classical behavior is clopen-ness; connectedness
forces contradiction). The bridge shows these are coordinates on one object. A
philosophical reading of Theorem~\ref{thm:connected}: it is the \emph{seamless}
(connected) worlds in which every nontrivial belief is dialetheic; to avoid all
impossible objects a space must already be disconnected.

\section{Future directions}

\begin{conjecture}[Clopen algebra is the largest classical sublogic]
For a space $X$, the Boolean algebra of clopen sets is the unique maximal
subfamily of closed sets on which $\contra A = \emptyset$ for every member, and
the valuation collapses to two values exactly there. ``How classical'' a space is
is measured by the cardinality of its clopen algebra. Building on
Theorem~\ref{thm:lnc-clopen}, the maximality claim is a finite combinatorial step,
testable on finite spaces and $\mathbb{R}^{n}$.
\end{conjecture}

\begin{conjecture}[Frontier dimension grades severity]
Order dialetheic closed sets by $\dim(\front A)$. In $\mathbb{R}^{n}$ the glut
content of a closed set is a monotone function of $\dim(\front A)$, with the
clopen case at the bottom; a point-frontier dialetheia ($[0,1]$) is smaller than
a hypersurface-frontier one (a closed ball). Via
Theorem~\ref{thm:contra-frontier} this reduces to dimension theory of frontiers;
the $n=1$ base case is computable from $\front[0,1]$.
\end{conjecture}

\begin{conjecture}[Retraction = interior; revision = closure]
Model non-monotone update by $A \mapsto \interior A$ (retraction: kills gluts) and
$A \mapsto \closure A$ (revision: may create gluts). Every finite sequence of
retract/revise operations stabilizes (reaches a regular open or regular closed
set).
\end{conjecture}

\section{Conclusion}

We formalized paraconsistent ``dream logic'' in two registers and proved them to
coincide. Belnap's $\FOUR$ hosts accepted contradictions without explosion
(\texttt{explosion\_fails}), with $\bothv$ the unique glut (\texttt{glut\_iff})
and $\neitherv$ the unique gap (\texttt{gap\_iff}). The closed-set topological
model identifies coexisting contradictions with boundaries
(\texttt{contradiction\_eq\_frontier}), classical behavior with clopen-ness
(\texttt{lnc\_holds\_iff\_clopen}), and proves that connectedness forces
paraconsistency (\texttt{connected\_forces\_paraconsistency}), with $0 \in [0,1]$
a concrete dialetheia (\texttt{dream\_object\_real}).

\end{document}

