function NEG(x): return (x.f, x.t)
function CONJ(x, y): return (x.t AND y.t, x.f OR y.f)
function DISJ(x, y): return (x.t OR y.t, x.f AND y.f)
function DESIGNATED(x): return x.t == 1

function EVALUATE(postfix_tokens, env):
    stack <- empty
    for tok in postfix_tokens:
        if tok == 'N': stack.push(NEG(stack.pop()))
        elif tok == 'C': b <- stack.pop(); a <- stack.pop(); stack.push(CONJ(a, b))
        elif tok == 'D': b <- stack.pop(); a <- stack.pop(); stack.push(DISJ(a, b))
        else: stack.push(env[tok])
    return stack.pop()

